+/// The pocket's ring strategies, with the pocket's default links.
+const STRATEGIES: [PocketStrategy; 2] = [PocketStrategy::Waterline, PocketStrategy::OffsetRings];
+
+fn pocket(strategy: PocketStrategy) -> PocketParams {
+    let mut p = params();
+    p.stepover = 2.0;
+    p.strategy = strategy;
+    p
+}
